   180→/// A wrapper around a `DataColumnSidecar` that indicates it has been approved for re-gossiping on
   181→/// the p2p network.
   182→#[derive(Debug)]
   183→pub struct GossipVerifiedDataColumn<T: BeaconChainTypes, O: ObservationStrategy = Observe> {
   184→    block_root: Hash256,
   185→    data_column: KzgVerifiedDataColumn<T::EthSpec>,
   186→    _phantom: PhantomData<O>,
   187→}
   188→
   189→impl<T: BeaconChainTypes, O: ObservationStrategy> Clone for GossipVerifiedDataColumn<T, O> {
   190→    fn clone(&self) -> Self {
   191→        Self {
   192→            block_root: self.block_root,
   193→            data_column: self.data_column.clone(),
   194→            _phantom: PhantomData,
   195→        }
   196→    }
   197→}
   198→
   199→impl<T: BeaconChainTypes, O: ObservationStrategy> GossipVerifiedDataColumn<T, O> {
   200→    pub fn new(
   201→        column_sidecar: Arc<DataColumnSidecar<T::EthSpec>>,
   202→        subnet_id: DataColumnSubnetId,
   203→        chain: &BeaconChain<T>,
   204→    ) -> Result<Self, GossipDataColumnError> {
   205→        let header = column_sidecar.signed_block_header.clone();
   206→        // We only process slashing info if the gossip verification failed
   207→        // since we do not process the data column any further in that case.
   208→        validate_data_column_sidecar_for_gossip::<T, O>(column_sidecar, subnet_id, chain).map_err(
   209→            |e| {
   210→                process_block_slash_info::<_, GossipDataColumnError>(
   211→                    chain,
   212→                    BlockSlashInfo::from_early_error_data_column(header, e),
   213→                )
   214→            },
   215→        )
   216→    }
   217→
   218→    /// Create a `GossipVerifiedDataColumn` from `DataColumnSidecar` for block production ONLY.
   219→    /// When publishing a block constructed locally, the EL will have already verified the cell proofs.
   220→    /// When publishing a block constructed externally, there will be no columns here.
   221→    pub fn new_for_block_publishing(
   222→        column_sidecar: Arc<DataColumnSidecar<T::EthSpec>>,
   223→        chain: &BeaconChain<T>,
   224→    ) -> Result<Self, GossipDataColumnError> {
   225→        verify_data_column_sidecar(&column_sidecar)?;
   226→
   227→        // Check if the data column is already in the DA checker cache. This happens when data columns
   228→        // are made available through the `engine_getBlobs` method.  If it exists in the cache, we know
   229→        // it has already passed the gossip checks, even though this particular instance hasn't been
   230→        // seen / published on the gossip network yet (passed the `verify_is_unknown_sidecar` check above).
   231→        // In this case, we should accept it for gossip propagation.
   232→        verify_is_unknown_sidecar(chain, &column_sidecar)?;
   233→
   234→        if chain
   235→            .data_availability_checker
   236→            .is_data_column_cached(&column_sidecar.block_root(), &column_sidecar)
   237→        {
   238→            // Observe this data column so we don't process it again.
   239→            if O::observe() {
   240→                observe_gossip_data_column(&column_sidecar, chain)?;
   241→            }
   242→            return Err(GossipDataColumnError::PriorKnownUnpublished);
   243→        }
   244→
   245→        Ok(Self {
   246→            block_root: column_sidecar.block_root(),
   247→            data_column: KzgVerifiedDataColumn::from_execution_verified(column_sidecar),
   248→            _phantom: Default::default(),
   249→        })
   250→    }
   251→
   252→    /// Create a `GossipVerifiedDataColumn` from `DataColumnSidecar` for testing ONLY.
   253→    pub fn __new_for_testing(column_sidecar: Arc<DataColumnSidecar<T::EthSpec>>) -> Self {
   254→        Self {
   255→            block_root: column_sidecar.block_root(),
   256→            data_column: KzgVerifiedDataColumn::__new_for_testing(column_sidecar),
   257→            _phantom: Default::default(),
   258→        }
   259→    }
   260→
   261→    pub fn as_data_column(&self) -> &DataColumnSidecar<T::EthSpec> {
   262→        self.data_column.as_data_column()
   263→    }
   264→
   265→    /// This is cheap as we're calling clone on an Arc
   266→    pub fn clone_data_column(&self) -> Arc<DataColumnSidecar<T::EthSpec>> {
   267→        self.data_column.clone_data_column()
   268→    }
   269→
   270→    pub fn block_root(&self) -> Hash256 {
   271→        self.block_root
   272→    }
   273→
   274→    pub fn slot(&self) -> Slot {
   275→        self.data_column.data.slot()
   276→    }
   277→
   278→    pub fn index(&self) -> ColumnIndex {
   279→        self.data_column.data.index
   280→    }
   281→
   282→    pub fn signed_block_header(&self) -> SignedBeaconBlockHeader {
   283→        self.data_column.data.signed_block_header.clone()
   284→    }
   285→
   286→    pub fn into_inner(self) -> KzgVerifiedDataColumn<T::EthSpec> {
   287→        self.data_column
   288→    }
   289→}
