use crate::beacon_block_body::{BLOB_KZG_COMMITMENTS_INDEX, KzgCommitments};
use crate::context_deserialize;
use crate::test_utils::TestRandom;
use crate::{
    BeaconBlockHeader, BeaconStateError, Epoch, EthSpec, ForkName, Hash256,
    SignedBeaconBlockHeader, Slot,
};
use bls::Signature;
use derivative::Derivative;
use kzg::Error as KzgError;
use kzg::{KzgCommitment, KzgProof};
use merkle_proof::verify_merkle_proof;
use safe_arith::ArithError;
use serde::{Deserialize, Serialize};
use ssz::Encode;
use ssz_derive::{Decode, Encode};
use ssz_types::Error as SszError;
use ssz_types::{FixedVector, VariableList};
use std::sync::Arc;
use test_random_derive::TestRandom;
use tree_hash::TreeHash;
use tree_hash_derive::TreeHash;

pub type ColumnIndex = u64;
pub type Cell<E> = FixedVector<u8, <E as EthSpec>::BytesPerCell>;
pub type DataColumn<E> = VariableList<Cell<E>, <E as EthSpec>::MaxBlobCommitmentsPerBlock>;

/// Identifies a set of data columns associated with a specific beacon block.
#[derive(Encode, Decode, Clone, Debug, PartialEq, TreeHash, Deserialize)]
#[context_deserialize(ForkName)]
pub struct DataColumnsByRootIdentifier<E: EthSpec> {
    pub block_root: Hash256,
    pub columns: VariableList<ColumnIndex, E::NumberOfColumns>,
}

pub type DataColumnSidecarList<E> = Vec<Arc<DataColumnSidecar<E>>>;

#[cfg_attr(
    feature = "arbitrary",
    derive(arbitrary::Arbitrary),
    arbitrary(bound = "E: EthSpec")
)]
#[derive(
    Debug, Clone, Serialize, Deserialize, Encode, Decode, TreeHash, TestRandom, Derivative,
)]
#[serde(bound = "E: EthSpec")]
#[derivative(PartialEq, Eq, Hash(bound = "E: EthSpec"))]
#[context_deserialize(ForkName)]
pub struct DataColumnSidecar<E: EthSpec> {
    #[serde(with = "serde_utils::quoted_u64")]
    pub index: ColumnIndex,
    #[serde(with = "ssz_types::serde_utils::list_of_hex_fixed_vec")]
    pub column: DataColumn<E>,
    /// All the KZG commitments and proofs associated with the block, used for verifying sample cells.
    pub kzg_commitments: KzgCommitments<E>,
    pub kzg_proofs: VariableList<KzgProof, E::MaxBlobCommitmentsPerBlock>,
    pub signed_block_header: SignedBeaconBlockHeader,
    /// An inclusion proof, proving the inclusion of `blob_kzg_commitments` in `BeaconBlockBody`.
    pub kzg_commitments_inclusion_proof: FixedVector<Hash256, E::KzgCommitmentsInclusionProofDepth>,
}

pub async fn process_gossip_data_columns(
    self: &Arc<Self>,
    data_columns: Vec<GossipVerifiedDataColumn<T>>,
    publish_fn: impl FnOnce() -> Result<(), BlockError>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
    let Ok((slot, block_root)) = data_columns
        .iter()
        .map(|c| (c.slot(), c.block_root()))
        .unique()
        .exactly_one()
    else {
        return Err(BlockError::InternalError(
            "Columns should be from the same block".to_string(),
        ));
    };

    // If this block has already been imported to forkchoice it must have been available, so
    // we don't need to process its samples again.
    if self
        .canonical_head
        .fork_choice_read_lock()
        .contains_block(&block_root)
    {
        return Err(BlockError::DuplicateFullyImported(block_root));
    }

    self.emit_sse_data_column_sidecar_events(
        &block_root,
        data_columns.iter().map(|column| column.as_data_column()),
    );

    let r = self
        .check_gossip_data_columns_availability_and_import(
            slot,
            block_root,
            data_columns,
            publish_fn,
        )
        .await;
    self.remove_notified(&block_root, r)
}

/// Cache the blobs in the processing cache, process it, then evict it from the cache if it was
/// imported or errors.
#[instrument(skip_all, level = "debug")]
pub async fn process_rpc_blobs(
    self: &Arc<Self>,
    slot: Slot,
    block_root: Hash256,
    blobs: FixedBlobSidecarList<T::EthSpec>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
    // If this block has already been imported to forkchoice it must have been available, so
    // we don't need to process its blobs again.
    if self
        .canonical_head
        .fork_choice_read_lock()
        .contains_block(&block_root)
    {
        return Err(BlockError::DuplicateFullyImported(block_root));
    }

    // Reject RPC blobs referencing unknown parents. Otherwise we allow potentially invalid data
    // into the da_checker, where invalid = descendant of invalid blocks.
    // Note: blobs should have at least one item and all items have the same parent root.
    if let Some(parent_root) = blobs
        .iter()
        .filter_map(|b| b.as_ref().map(|b| b.block_parent_root()))
        .next()
        && !self
            .canonical_head
            .fork_choice_read_lock()
            .contains_block(&parent_root)
    {
        return Err(BlockError::ParentUnknown { parent_root });
    }

    self.emit_sse_blob_sidecar_events(&block_root, blobs.iter().flatten().map(Arc::as_ref));

    let r = self
        .check_rpc_blob_availability_and_import(slot, block_root, blobs)
        .await;
    self.remove_notified(&block_root, r)
}

/// Process blobs retrieved from the EL and returns the `AvailabilityProcessingStatus`.
pub async fn process_engine_blobs(
    self: &Arc<Self>,
    slot: Slot,
    block_root: Hash256,
    engine_get_blobs_output: EngineGetBlobsOutput<T>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
